INSERT INTO `HomeService` VALUES ('cmsfjcehs000ol22kp8ztwu0q','Personalized Counseling','personalized-counseling','MessageCircle','One-on-one sessions with experienced counselors to understand your goals, preferences, and create a tailored study abroad plan.','Book Free Consultation','/contact',1,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjcehs000pl22k9vgckasr','University Selection','university-selection','GraduationCap','Expert guidance to find the best-fit universities based on your academic profile, budget, career goals, and preferred destination.','Find Universities','/course-finder',2,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjcehs000ql22krvb79uuy','Course Matching','course-matching','BookOpen','AI-powered and expert-verified course recommendations matched to your academic background, interests, and career aspirations.','Match Courses','/course-finder',3,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjcehs000rl22ktz1vl95o','Application Assistance','application-assistance','FileText','End-to-end support with university applications including form filling, document compilation, submission tracking, and offer management.','Start Application','/contact',4,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjcehs000sl22k8t0k0t1y','SOP and CV Support','sop-cv-support','PenTool','Professional help crafting compelling Statements of Purpose and CVs that highlight your strengths and impress admissions committees.','Get SOP Help','/contact',5,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjcehs000tl22ko9r3dskq','Document Checking','document-checking','ClipboardCheck','Thorough review of all your application documents to ensure accuracy, completeness, and compliance with university requirements.','Check Documents','/contact',6,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjcehs000ul22kz4gv0fuy','Visa Guidance','visa-guidance','Plane','Step-by-step visa application support including document preparation, mock interviews, and submission guidance for your target country.','Visa Support','/contact',7,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjcehs000vl22kq9dklycz','Interview Preparation','interview-preparation','Mic','Mock interviews and coaching for university admissions interviews and visa interviews to build your confidence and communication skills.','Prepare Now','/contact',8,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjcehs000wl22kfb7f29cx','English Test Preparation','english-test-preparation','Languages','Comprehensive preparation programs for IELTS, PTE, TOEFL, and Duolingo with expert instructors, practice materials, and mock tests.','Prepare for Tests','/english-tests',9,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjceht000xl22ktuu9p2pu','Financial Planning','financial-planning','Wallet','Guidance on tuition costs, living expenses, scholarship opportunities, bank loans, and proof-of-funds documentation for visa applications.','Plan Finances','/contact',10,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjceht000yl22k3ucu09ly','Scholarship Guidance','scholarship-guidance','Award','Identification and application support for scholarships, grants, and bursaries to reduce the financial burden of studying abroad.','Find Scholarships','/scholarships',11,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjceht000zl22kh98l60ez','Pre-Departure Orientation','pre-departure-orientation','Luggage','Comprehensive pre-departure briefings covering accommodation, banking, healthcare, cultural tips, and what to expect in your new country.','Join Orientation','/contact',12,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjceht0010l22k44w5gs3d','Post-Arrival Support','post-arrival-support','MapPin','On-the-ground assistance in your destination country including airport pickup, accommodation setup, and settling-in support.','Get Support','/contact',13,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjceht0011l22ki9z5wh26','Career Counseling','career-counseling','Briefcase','Professional career advice to help you choose the right course and university that aligns with your long-term career goals and industry demand.','Career Advice','/contact',14,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521'),('cmsfjceht0012l22kjn8tf5ar','Ongoing Mentorship','ongoing-mentorship','Users','Continuous support and mentorship throughout your study abroad journey — from application to graduation and beyond.','Connect with Mentor','/contact',15,'active','2026-08-05 03:36:39.521','2026-08-05 03:36:39.521');
